CREATE DATABASE IF NOT EXISTS pips_school_erp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pips_school_erp;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','principal','admin_officer','teacher','accountant','hr_officer') NOT NULL DEFAULT 'admin_officer',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE students(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admission_no VARCHAR(50) NOT NULL UNIQUE,full_name VARCHAR(150) NOT NULL,class_name VARCHAR(80),section_name VARCHAR(40),date_of_birth DATE,gender ENUM('Male','Female','Other') NOT NULL,guardian_name VARCHAR(150),guardian_phone VARCHAR(30),status ENUM('active','inactive','graduated','withdrawn') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE staff(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_no VARCHAR(50) NOT NULL UNIQUE,full_name VARCHAR(150) NOT NULL,designation VARCHAR(100),department VARCHAR(100),phone VARCHAR(30),email VARCHAR(190),joining_date DATE,status ENUM('active','inactive','left') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE school_classes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,class_name VARCHAR(80) NOT NULL,section_name VARCHAR(40) NOT NULL,academic_year VARCHAR(20) NOT NULL,room_no VARCHAR(30),UNIQUE KEY uq_class_section_year(class_name,section_name,academic_year)) ENGINE=InnoDB;
CREATE TABLE subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subject_code VARCHAR(30) NOT NULL UNIQUE,subject_name VARCHAR(100) NOT NULL,class_name VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE student_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','late','leave') NOT NULL,marked_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_student_day(student_id,attendance_date),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(marked_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE staff_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','late','leave') NOT NULL,UNIQUE KEY uq_staff_day(staff_id,attendance_date),FOREIGN KEY(staff_id) REFERENCES staff(id)) ENGINE=InnoDB;
CREATE TABLE examinations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_name VARCHAR(150) NOT NULL,academic_year VARCHAR(20) NOT NULL,start_date DATE,end_date DATE,status ENUM('planned','ongoing','completed') NOT NULL DEFAULT 'planned',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE question_papers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,examination_id INT UNSIGNED NOT NULL,class_name VARCHAR(80) NOT NULL,subject_name VARCHAR(100) NOT NULL,stored_file VARCHAR(255) NOT NULL,uploaded_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(examination_id) REFERENCES examinations(id),FOREIGN KEY(uploaded_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE exam_marks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,examination_id INT UNSIGNED NOT NULL,student_id INT UNSIGNED NOT NULL,subject_name VARCHAR(100) NOT NULL,total_marks DECIMAL(8,2) NOT NULL,obtained_marks DECIMAL(8,2) NOT NULL,entered_by INT UNSIGNED NOT NULL,UNIQUE KEY uq_exam_student_subject(examination_id,student_id,subject_name),CHECK(obtained_marks<=total_marks),FOREIGN KEY(examination_id) REFERENCES examinations(id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(entered_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE fee_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,receipt_no VARCHAR(60) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,payment_method VARCHAR(40),paid_on DATE NOT NULL,received_by INT UNSIGNED NOT NULL,notes VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE fee_appreciation_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id INT UNSIGNED NOT NULL,appreciation_month DATE NOT NULL,marks_awarded DECIMAL(6,2) NOT NULL DEFAULT 0,eligibility_status ENUM('pending','eligible','not_eligible','approved') NOT NULL DEFAULT 'pending',notes VARCHAR(500),created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_app_student_month(student_id,appreciation_month),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE guardians(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(190),relationship ENUM('Father','Mother','Guardian','Other') NOT NULL,address VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE announcements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,publish_date DATE NOT NULL,audience ENUM('all','students','parents','staff') NOT NULL) ENGINE=InnoDB;
